<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;

if(Auth::role()!=='super_admin'){http_response_code(403);exit('Acesso restrito ao Super ADM.');}
$moduleLabels=['menu'=>'Cardápio Digital / PDV','delivery'=>'Delivery / Retirada','restaurant'=>'Mesas / Cozinha','events'=>'Eventos / Ingressos','loyalty'=>'CRM / Fidelidade'];
function sa_settings(array $tenant):array{$v=json_decode((string)($tenant['settings']??'{}'),true);return is_array($v)?$v:[];}
function sa_type_label(string $type):string{return match($type){'events'=>'Eventos','menu'=>'Cardápio Digital','both'=>'Eventos + Cardápio',default=>'Não definido'};}
function sa_default_modules(string$type):array{return match($type){'events'=>['events'=>1,'loyalty'=>1],'menu'=>['menu'=>1,'delivery'=>1,'restaurant'=>1,'loyalty'=>1],default=>['menu'=>1,'delivery'=>1,'restaurant'=>1,'events'=>1,'loyalty'=>1]};}

if($_SERVER['REQUEST_METHOD']==='POST'){
 em_post_csrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='select-tenant'){$id=(int)($_POST['tenant_id']??0);Auth::selectTenant($id>0?$id:null);Auth::audit('superadmin.tenant_selected','tenant',$id?(string)$id:null);em_flash('ok',$id?'Cliente selecionado. Você está operando dentro desta conta.':'Contexto global selecionado.');em_go('superadmin');}
  if($action==='tenant-status'){$id=(int)$_POST['tenant_id'];$status=(string)($_POST['status']??'active');if(!in_array($status,['active','suspended','cancelled'],true))throw new RuntimeException('Status inválido.');$s=$pdo->prepare('UPDATE tenants SET status=? WHERE id=?');$s->execute([$status,$id]);$c=$pdo->prepare('SELECT id FROM tenants WHERE id=?');$c->execute([$id]);if(!$c->fetchColumn())throw new RuntimeException('Cliente não encontrado.');if(Auth::tenantId()===$id&&$status!=='active')Auth::selectTenant(null);Auth::audit('superadmin.tenant_status','tenant',(string)$id,['status'=>$status]);em_flash('ok','Status do cliente atualizado.');em_go('superadmin',['edit'=>$id]);}
  if($action==='tenant-create'){
   $company=trim((string)($_POST['company']??''));$admin=trim((string)($_POST['admin_name']??''));$email=mb_strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$plan=trim((string)($_POST['plan']??'premium'));$phone=trim((string)($_POST['phone']??''));$taxId=preg_replace('/\D+/','',(string)($_POST['tax_id']??''))??'';$businessType=(string)($_POST['business_type']??'both');
   if($company===''||$admin===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<10)throw new RuntimeException('Preencha empresa, administrador, e-mail válido e senha com 10+ caracteres.');if(!preg_match('/^[a-zA-Z0-9_-]{2,40}$/',$plan))throw new RuntimeException('Plano inválido.');if(!in_array($businessType,['events','menu','both'],true))throw new RuntimeException('Tipo de negócio inválido.');if($taxId!==''&&!in_array(strlen($taxId),[11,14],true))throw new RuntimeException('CPF/CNPJ deve ter 11 ou 14 dígitos.');
   $slug=em_slug($company).'-'.substr(bin2hex(random_bytes(3)),0,6);$settings=['business_type'=>$businessType,'tax_id'=>$taxId,'whatsapp'=>$phone];$defaults=sa_default_modules($businessType);
   Database::transaction(function(PDO$db)use($company,$slug,$admin,$email,$password,$plan,$phone,$settings,$moduleLabels,$defaults,&$tenantId){$db->prepare('INSERT INTO tenants (name,slug,plan,status,phone,primary_color,secondary_color,settings) VALUES (?,?,?,"active",?,"#6d4aff","#8b5cf6",?)')->execute([$company,$slug,$plan,$phone?:null,json_encode($settings,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$tenantId=(int)$db->lastInsertId();$db->prepare('INSERT INTO users (tenant_id,name,email,password_hash,role,status) VALUES (?,?,?,?,"admin","active")')->execute([$tenantId,$admin,$email,password_hash($password,PASSWORD_DEFAULT)]);$m=$db->prepare('INSERT INTO tenant_modules (tenant_id,module_key,enabled) VALUES (?,?,?)');foreach(array_keys($moduleLabels)as$key)$m->execute([$tenantId,$key,isset($defaults[$key])?1:0]);});
   Auth::audit('superadmin.tenant_created','tenant',(string)$tenantId,['admin_email'=>$email,'plan'=>$plan,'business_type'=>$businessType]);em_flash('ok','Cliente criado com administrador e módulos iniciais.');em_go('superadmin',['edit'=>$tenantId]);
  }
  if($action==='tenant-settings'){
   $id=(int)($_POST['tenant_id']??0);$name=trim((string)($_POST['name']??''));$plan=trim((string)($_POST['plan']??'premium'));$domain=trim((string)($_POST['custom_domain']??''));$support=mb_strtolower(trim((string)($_POST['support_email']??'')));$phone=trim((string)($_POST['phone']??''));$taxId=preg_replace('/\D+/','',(string)($_POST['tax_id']??''))??'';$businessType=(string)($_POST['business_type']??'both');$primary=trim((string)($_POST['primary_color']??'#6d4aff'));$secondary=trim((string)($_POST['secondary_color']??'#8b5cf6'));$expires=trim((string)($_POST['plan_expires_at']??''));
   if($name===''||!preg_match('/^[a-zA-Z0-9_-]{2,40}$/',$plan))throw new RuntimeException('Dados do cliente inválidos.');if(!in_array($businessType,['events','menu','both'],true))throw new RuntimeException('Tipo de negócio inválido.');if($taxId!==''&&!in_array(strlen($taxId),[11,14],true))throw new RuntimeException('CPF/CNPJ deve ter 11 ou 14 dígitos.');if($support!==''&&!filter_var($support,FILTER_VALIDATE_EMAIL))throw new RuntimeException('E-mail de suporte inválido.');if($domain!==''&&!preg_match('/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i',$domain))throw new RuntimeException('Domínio personalizado inválido.');foreach([$primary,$secondary]as$color)if(!preg_match('/^#[0-9a-fA-F]{6}$/',$color))throw new RuntimeException('Cor inválida.');$expires=$expires?str_replace('T',' ',$expires):null;
   Database::transaction(function(PDO$db)use($id,$name,$plan,$domain,$support,$phone,$taxId,$businessType,$primary,$secondary,$expires,$moduleLabels){$c=$db->prepare('SELECT settings FROM tenants WHERE id=?');$c->execute([$id]);$raw=$c->fetchColumn();if($raw===false)throw new RuntimeException('Cliente não encontrado.');$settings=json_decode((string)($raw?:'{}'),true);if(!is_array($settings))$settings=[];$settings['business_type']=$businessType;$settings['tax_id']=$taxId;$settings['whatsapp']=$phone;$db->prepare('UPDATE tenants SET name=?,plan=?,plan_expires_at=?,custom_domain=?,support_email=?,phone=?,primary_color=?,secondary_color=?,settings=? WHERE id=?')->execute([$name,$plan,$expires,$domain?:null,$support?:null,$phone?:null,$primary,$secondary,json_encode($settings,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$id]);$up=$db->prepare('INSERT INTO tenant_modules (tenant_id,module_key,enabled) VALUES (?,?,?) ON DUPLICATE KEY UPDATE enabled=VALUES(enabled)');foreach(array_keys($moduleLabels)as$key)$up->execute([$id,$key,isset($_POST['module'][$key])?1:0]);});
   Auth::audit('superadmin.tenant_settings','tenant',(string)$id,['plan'=>$plan,'domain'=>$domain,'business_type'=>$businessType]);em_flash('ok','Cliente, plano e módulos atualizados.');em_go('superadmin',['edit'=>$id]);
  }
 }catch(Throwable$e){em_flash('error',$e->getMessage());em_go('superadmin');}
}

$editId=(int)($_GET['edit']??0);$edit=null;$editModules=[];$editSettings=[];
if($editId){$s=$pdo->prepare('SELECT * FROM tenants WHERE id=?');$s->execute([$editId]);$edit=$s->fetch()?:null;if($edit){$editSettings=sa_settings($edit);$m=$pdo->prepare('SELECT module_key,enabled FROM tenant_modules WHERE tenant_id=?');$m->execute([$editId]);foreach($m->fetchAll()as$r)$editModules[$r['module_key']]=(bool)$r['enabled'];}}
$q=trim((string)($_GET['q']??''));$statusFilter=(string)($_GET['status']??'all');if(!in_array($statusFilter,['all','active','suspended','cancelled'],true))$statusFilter='all';
$sql='SELECT t.*,(SELECT COUNT(*) FROM users u WHERE u.tenant_id=t.id) users_count,(SELECT COUNT(*) FROM business_units bu WHERE bu.tenant_id=t.id AND bu.status="active") units_count,(SELECT COUNT(*) FROM orders o WHERE o.tenant_id=t.id) orders_count,(SELECT COALESCE(SUM(o.total_cents),0) FROM orders o WHERE o.tenant_id=t.id AND o.payment_status="paid") paid_total FROM tenants t';$args=[];if($statusFilter!=='all'){$sql.=' WHERE t.status=?';$args[]=$statusFilter;}$sql.=' ORDER BY t.id DESC';$s=$pdo->prepare($sql);$s->execute($args);$tenants=$s->fetchAll();foreach($tenants as&$t)$t['_settings']=sa_settings($t);unset($t);
if($q!==''){$needle=mb_strtolower($q);$tenants=array_values(array_filter($tenants,function($t)use($needle){$st=$t['_settings'];$hay=mb_strtolower(implode(' ',[(string)$t['name'],(string)$t['slug'],(string)($t['support_email']??''),(string)($t['custom_domain']??''),(string)($t['phone']??''),(string)($st['tax_id']??''),sa_type_label((string)($st['business_type']??''))]));return str_contains($hay,$needle);}));}
$overview=$pdo->query('SELECT COUNT(*) total,SUM(CASE WHEN status="active" THEN 1 ELSE 0 END) active,SUM(CASE WHEN status="suspended" THEN 1 ELSE 0 END) suspended FROM tenants')->fetch();$paidGlobal=(int)$pdo->query('SELECT COALESCE(SUM(total_cents),0) FROM orders WHERE payment_status="paid"')->fetchColumn();$selected=Auth::tenantId();
em_header('Clientes','superadmin');
?>
<style>.sa-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:15px}.sa-head h2{margin:0;font-size:23px}.sa-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin-bottom:16px}.sa-stat{background:#fff;border:1px solid var(--line);border-radius:14px;padding:16px}.sa-stat span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;font-weight:850}.sa-stat strong{display:block;font-size:25px;margin-top:5px}.sa-filter{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:14px}.sa-filter a{padding:8px 12px;border-radius:999px;border:1px solid var(--line);font-size:10px;font-weight:850;color:#747487}.sa-filter a.active{background:var(--accent-soft);border-color:#dcd3ff;color:var(--accent)}.sa-client-list{display:grid;gap:9px}.sa-client{display:grid;grid-template-columns:minmax(200px,1.45fr) 135px 105px 130px auto;gap:12px;align-items:center;background:#fff;border:1px solid var(--line);border-radius:14px;padding:14px}.sa-client small{display:block;color:var(--muted);margin-top:3px}.sa-client .actions{justify-content:flex-end}.sa-edit-grid{display:grid;grid-template-columns:minmax(320px,.95fr) minmax(0,1.45fr);gap:16px;margin-bottom:16px}.module-grid,.business-type-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.business-card{display:block;border:1px solid var(--line);border-radius:13px;padding:12px}.business-card input{width:auto;min-height:0}.business-card strong{display:block;margin:4px 0}.business-card small{color:var(--muted)}@media(max-width:1050px){.sa-client{grid-template-columns:1fr 130px auto}.sa-client .sa-structure,.sa-client .sa-paid{display:none}}@media(max-width:800px){.sa-edit-grid{grid-template-columns:1fr}.sa-stats{grid-template-columns:1fr 1fr}.sa-client{grid-template-columns:1fr auto}.sa-client .sa-type,.sa-client .sa-status{display:none}.sa-head{align-items:flex-start;flex-direction:column}}@media(max-width:520px){.module-grid,.business-type-grid{grid-template-columns:1fr}}</style>
<section class="sa-head"><div><h2>Clientes do EventMenu</h2><p class="muted">Gerencie seus clientes cadastrados.</p></div><div class="actions"><a class="button secondary" href="<?= Security::e(em_url('/?route=backup')) ?>">Backup</a><a class="button primary" href="<?= Security::e(em_url('/?route=superadmin&new=1')) ?>">+ Novo Cliente</a></div></section>
<section class="sa-stats"><div class="sa-stat"><span>Clientes</span><strong><?= (int)($overview['total']??0) ?></strong></div><div class="sa-stat"><span>Ativos</span><strong><?= (int)($overview['active']??0) ?></strong></div><div class="sa-stat"><span>Suspensos</span><strong><?= (int)($overview['suspended']??0) ?></strong></div><div class="sa-stat"><span>Volume recebido</span><strong style="font-size:18px"><?= em_money($paidGlobal) ?></strong></div></section>
<?php if(isset($_GET['new'])||$edit):?><section class="sa-edit-grid"><?php if(isset($_GET['new'])):?><article class="card"><div class="section-head"><div><h2>Novo Cliente</h2><p class="muted">Cadastre um novo cliente na plataforma.</p></div><a class="button secondary" href="<?= Security::e(em_url('/?route=superadmin')) ?>">Cancelar</a></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tenant-create"><label class="span-2">Nome / Razão Social<input name="company" required></label><label>E-mail<input type="email" name="email" required></label><label>WhatsApp<input name="phone" placeholder="(11) 99999-9999"></label><label class="span-2">CNPJ / CPF<input name="tax_id" inputmode="numeric"></label><div class="span-2"><strong>Tipo de Negócio</strong><p class="muted">Escolha o tipo que melhor descreve o cliente.</p><div class="business-type-grid"><label class="business-card"><input type="radio" name="business_type" value="events" required><strong>Eventos</strong><small>Venda de ingressos para eventos, shows, festas e experiências.</small></label><label class="business-card"><input type="radio" name="business_type" value="menu" required><strong>Cardápio Digital</strong><small>Restaurantes, bares, lanchonetes e delivery.</small></label><label class="business-card"><input type="radio" name="business_type" value="both" checked><strong>Completo</strong><small>Eventos + Cardápio Digital no mesmo cliente.</small></label></div></div><label>Administrador<input name="admin_name" required></label><label>Plano<input name="plan" value="premium" required></label><label class="span-2">Senha inicial<input type="password" name="password" minlength="10" required></label><button class="primary span-2">Salvar Cliente</button></form></article><?php endif;?><?php if($edit):?><article class="card"><div class="section-head"><div><h2><?= Security::e($edit['name']) ?></h2><p class="muted">Dados, plano, marca e módulos.</p></div><a class="button secondary" href="<?= Security::e(em_url('/?route=superadmin')) ?>">Fechar</a></div><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tenant-settings"><input type="hidden" name="tenant_id" value="<?= $editId ?>"><label class="span-2">Nome / Razão Social<input name="name" required value="<?= Security::e($edit['name']) ?>"></label><label>WhatsApp<input name="phone" value="<?= Security::e($edit['phone']??'') ?>"></label><label>CNPJ / CPF<input name="tax_id" value="<?= Security::e($editSettings['tax_id']??'') ?>"></label><label>Tipo de negócio<select name="business_type"><option value="events"<?= em_selected($editSettings['business_type']??'both','events') ?>>Eventos</option><option value="menu"<?= em_selected($editSettings['business_type']??'both','menu') ?>>Cardápio Digital</option><option value="both"<?= em_selected($editSettings['business_type']??'both','both') ?>>Completo</option></select></label><label>Plano<input name="plan" value="<?= Security::e($edit['plan']) ?>"></label><label>Vencimento<input type="datetime-local" name="plan_expires_at" value="<?= $edit['plan_expires_at']?Security::e(date('Y-m-d\TH:i',strtotime($edit['plan_expires_at']))):'' ?>"></label><label class="span-2">Domínio personalizado<input name="custom_domain" value="<?= Security::e($edit['custom_domain']??'') ?>"></label><label>E-mail de suporte<input type="email" name="support_email" value="<?= Security::e($edit['support_email']??'') ?>"></label><label>Cor principal<input type="color" name="primary_color" value="<?= Security::e($edit['primary_color']??'#6d4aff') ?>"></label><label>Cor secundária<input type="color" name="secondary_color" value="<?= Security::e($edit['secondary_color']??'#8b5cf6') ?>"></label><div class="span-2"><strong>Módulos do cliente</strong><div class="module-grid" style="margin-top:8px"><?php foreach($moduleLabels as$key=>$label):?><label class="checkbox"><input type="checkbox" name="module[<?= Security::e($key) ?>]"<?= em_checked($editModules[$key]??true) ?>> <?= Security::e($label) ?></label><?php endforeach;?></div></div><button class="primary span-2">Salvar alterações</button></form></article><?php endif;?></section><?php endif;?>
<section class="card"><div class="section-head"><form method="get" class="actions" style="flex:1"><input type="hidden" name="route" value="superadmin"><input name="q" value="<?= Security::e($q) ?>" placeholder="Buscar cliente, contato ou CPF/CNPJ" style="max-width:360px"><input type="hidden" name="status" value="<?= Security::e($statusFilter) ?>"><button class="secondary">Buscar</button></form><span class="muted"><?= count($tenants) ?> resultado(s)</span></div><nav class="sa-filter"><?php foreach(['all'=>'Todos','active'=>'Ativos','suspended'=>'Suspensos','cancelled'=>'Cancelados']as$key=>$label):?><a class="<?= $statusFilter===$key?'active':'' ?>" href="<?= Security::e(em_url('/?route=superadmin&status='.$key.($q!==''?'&q='.urlencode($q):''))) ?>"><?= Security::e($label) ?></a><?php endforeach;?></nav><div class="sa-client-list"><?php foreach($tenants as$t):$st=$t['_settings'];?><div class="sa-client"><div><strong><?= Security::e($t['name']) ?></strong><?php if($selected===(int)$t['id']):?> <span class="badge active">Em uso</span><?php endif;?><small><?= Security::e($t['phone']??$t['support_email']??$t['slug']) ?></small></div><div class="sa-type"><small>Tipo</small><strong><?= Security::e(sa_type_label((string)($st['business_type']??''))) ?></strong></div><div class="sa-status"><small>Status</small><span class="badge <?= $t['status']==='active'?'active':'' ?>"><?= Security::e(match($t['status']){'active'=>'Ativo','suspended'=>'Suspenso','cancelled'=>'Cancelado',default=>$t['status']}) ?></span></div><div class="sa-paid"><small>Recebido</small><strong><?= em_money($t['paid_total']) ?></strong></div><div class="actions"><a class="button secondary" href="<?= Security::e(em_url('/?route=superadmin&edit='.(int)$t['id'])) ?>">Editar</a><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="select-tenant"><input type="hidden" name="tenant_id" value="<?= (int)$t['id'] ?>"><button class="secondary">Acessar</button></form><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="tenant-status"><input type="hidden" name="tenant_id" value="<?= (int)$t['id'] ?>"><input type="hidden" name="status" value="<?= $t['status']==='active'?'suspended':'active' ?>"><button class="secondary"><?= $t['status']==='active'?'Suspender':'Ativar' ?></button></form></div></div><?php endforeach;?><?php if(!$tenants):?><div class="alert">Nenhum cliente encontrado.</div><?php endif;?></div></section>
<?php em_footer();
